bool IsDangerousDownload(const DownloadItem& download, const FilePath& suggested_path, bool visited_referrer_before) {
  // Check if off-store extension installation is allowed
  if (!IsOffStoreExtensionInstallAllowed(download)) {
    return true;
  }

  // Check if the download is an extension without approval
  if (IsExtensionDownload(download) && !download.approved) {
    return true;
  }

  // Check if the file should be opened based on user gestures
  if (!IsDownloadTriggeredByUserGesture(download)) {
    return true;
  }

  // Check the danger level of the file
  if (GetFileDangerLevel(suggested_path) != DANGER_LEVEL_SAFE) {
    return true;
  }

  // If the referrer page has not been visited before, consider the download dangerous
  if (!visited_referrer_before) {
    return true;
  }

  return false;
}

bool IsDownloadDangerous(const DownloadItem& download, const FilePath& suggested_path, bool visited_referrer_before) {
  // Check if off-store extension installation is enabled and if the download is
  // an extension without approval
  bool is_extension = download.IsExtension();
  bool is_offstore_install_allowed = IsOffStoreExtensionInstallAllowed();
  bool is_approved_extension = IsExtensionApproved(download);

  if (is_extension && !is_approved_extension) {
    return true;
  }

  // Check if the file should be opened based on user gestures
  if (!download.IsUserGestureTriggered()) {
    return true;
  }

  // Check the danger level of the file
  if (download.GetDangerLevel() == DANGEROUS) {
    return true;
  }

  // Consider referrer history
  if (!visited_referrer_before) {
    return true;
  }

  return false;
}

bool IsDownloadDangerous(const DownloadItem& download, const FilePath& suggested_path, bool visited_referrer_before) {
  bool is_extension = IsExtensionDownload(download);
  bool is_off_store_installation_enabled = IsOffStoreExtensionInstallAllowed();

  // Check if it's an extension without user approval
  if (is_extension && !download.approved) {
    return true;
  }

  // Check if the file should be opened based on user gesture
  if (!download.user_initiated && !visited_referrer_before) {
    return true;
  }

  // Evaluate the danger level of the file based on its type
  if (IsDangerousFileExtension(suggested_path)) {
    return true;
  }

  return false;
