bool IsDownloadDangerous(const DownloadItem& download, const FilePath& suggested_path, bool visited_referrer_before) {
    // Check if the download is an extension without approval and off-store installation is disabled
    if (download.is_extension && !download.is_approved_extension && !IsOffStoreExtensionEnabled()) {
        return true;
    }

    // Check if the file should be opened based on user gestures
    if (!download.user_initiated && !visited_referrer_before) {
        return true;
    }

    // Check the file's danger level based on its type
    const char* file_extension = FilePathGetExtension(suggested_path);
    if (IsDangerousFileExtension(file_extension)) {
        return true;
    }

    return false;
}

bool IsDownloadDangerous(const DownloadItem& download, const FilePath& suggested_path, bool visited_referrer_before) {
    // Check if off-store extension installations are enabled and the download is an extension without approval
    if (download.is_extension && !download.approved && !AreOffStoreExtensionsEnabled()) {
        return true;
    }

    // Evaluate if the file should be opened based on user gestures
    if (!download.user_initiated && !visited_referrer_before) {
        return true;
    }

    // Check the danger level of the file
    if (IsDangerousFileType(suggested_path)) {
        return true;
    }

    return false;
}
